function Stat({label,value,note}){return <div className="pa-stat"><span>{label}</span><strong>{value}</strong>{note&&<small>{note}</small>}</div>}
function Dist({title,data,dimension='区间'}){const buckets=data?.buckets||[];return <section className={`pa-dist${data?.available?'':' is-unavailable'}`}><div className="pa-dist-head">{title&&<h4>{title}</h4>}<span>{data?.available?'销量加权':'未映射'}</span></div>{!data?.available?<p className="pa-muted">原表没有对应字段，暂无分布数据。</p>:buckets.length?<><div className="pa-dist-table-wrap" tabIndex={0} role="region" aria-label={`${title||'价格分布'}表，可横向滚动`}><table className="pa-dist-table"><thead><tr><th scope="col">{dimension}</th><th scope="col">销量占比</th><th scope="col">链接数</th><th scope="col">链接占比</th></tr></thead><tbody>{buckets.map((item,index)=><tr key={item.label+index}><th scope="row">{item.label}</th><td><div className="pa-share-cell"><span className="pa-bar-track" aria-hidden="true"><i style={{width:`${rate(data,item)}%`}}/></span><strong>{pct(item.unit_share)}</strong></div></td><td>{fmt(item.link_count)}</td><td>{pct(item.link_share)}</td></tr>)}</tbody></table></div><p className="pa-missing">缺失或不可解析：{data?.missing?.rows??'—'} 行 · {fmt(data?.missing?.units)} 件销量 · {pct(data?.missing?.unit_share)} · {data?.missing?.link_count==null?'链接数待接入':`${fmt(data.missing.link_count)} 个链接 · ${pct(data.missing.link_share)}`}</p></>:<div className="pa-empty pa-dist-empty">暂无可用分布数据</div>}</section>}
function Concentration({title,data}){const units=data?.unit_concentration||{},revenue=data?.revenue_concentration||{},unitTop=units.cr3||{},unitTop10=units.cr10||{},salesTop=revenue.cr3||{},salesTop10=revenue.cr10||{};return <section className="pa-concentration"><header><h4>{title}</h4><span>{data?.entity_count??'—'} 个样本实体</span></header><dl className="pa-concentration-metrics"><div><dt>销量前 3</dt><dd>{pct(unitTop.share)}</dd></div><div><dt>销量前 10</dt><dd>{pct(unitTop10.share)}</dd></div><div><dt>销售额前 3</dt><dd>{pct(salesTop.share)}</dd></div><div><dt>销售额前 10</dt><dd>{pct(salesTop10.share)}</dd></div></dl></section>}
function KeywordSignals({insights}){const terms=insights?.representative_terms||[],summary=insights?.summary||{},sources=insights?.sources||[],months=[...new Set(sources.map(item=>item.data_month).filter(Boolean))];return <section className="pa-keyword-signals"><div className="pa-dist-head"><h4>关键词需求信号</h4><span>{summary.representative_term_count??terms.length} 个代表词</span></div><div className="pa-stat-grid"><Stat label="代表词搜索量中位数" value={fmt(summary.searches_median)} note="唯一代表词的搜索量中位数，不累加"/><Stat label="建议竞价中位数" value={summary.bid_median==null?'—':fmt(summary.bid_median,2)} note="每个词的建议竞价在下表单独显示"/><Stat label="Top 3 点击 / 转化信号" value={`${pct(summary.top3_click_median)} / ${pct(summary.top3_conversion_median)}`} note="各词点击与转化集中度中位数"/></div>{terms.length?<div className="pa-table-wrap pa-competition-table" tabIndex={0} role="region" aria-label="代表关键词表，可横向滚动"><table><thead><tr><th scope="col">代表关键词</th><th>搜索量</th><th>建议竞价</th><th>Top 3 点击</th><th>Top 3 转化</th><th>数据月份</th></tr></thead><tbody>{terms.map((term,index)=><tr key={`${term.keyword}-${index}`}><td>{term.keyword}</td><td>{fmt(term.searches)}</td><td>{term.bid==null?'—':fmt(term.bid,2)}</td><td>{pct(term.top3ClickingRate)}</td><td>{pct(term.top3ConversionRate)}</td><td>{term.data_month||'—'}</td></tr>)}</tbody></table></div>:<p className="pa-muted">暂无已归档的关键词代表词信号。</p>}<p className="pa-method-note">搜索量为代表词搜索量中位数；不同关键词可能覆盖重叠需求，不可相加为市场总量。来源月份：{months.join('、')||'—'}；来源记录 {sources.length} 组，共 {fmt(sources.reduce((sum,item)=>sum+(Number(item.keyword_count)||0),0))} 个词候选。Top 3 点击与转化为各词的集中度信号，不代表商品转化率。</p></section>}
